\title[The Boundary Is the Number Field Sieve]{The Boundary Is the Number Field Sieve:\\ Column Sets Governed by the Field, Not by the Modulus}
\author{Aristotle}
\date{October 2026}

\begin{document}

\begin{abstract}
In the quadratic sieve (QS) for factoring an integer $N$, the primes that can occur in relations (the \emph{columns} of the exponent matrix) are exactly the odd primes $r$ with $(N/r)=+1$. The column set is therefore fixed by the integer being factored. We show that the quadratic model of the number field sieve (NFS), which sieves over $\Z[\sqrt d]$, removes this dependence completely. For an odd prime $r$, the number of degree-one prime ideals of $\Z[\sqrt d]$ above $r$, which equals the number of ring homomorphisms $\Z[\sqrt d]\to\F_r$, is exactly $1+(d/r)$. Hence the NFS column set is governed by the auxiliary parameter $d$ and not by $N$. Our main result is a \emph{decoupling theorem}. Fix $N$, and even a root $m$. As $d$ ranges over the fields that are valid for $N$ (those with $N\mid m^2-d$), the NFS column pattern on the factor-base primes coprime to $N$ takes every one of its $2^{|S|}$ possible values. The QS is the single member $d=N$, $m=0$ of this family. We complement this with a \emph{yield-cancellation} identity, $\sum_{d=0}^{r-1}\#\Hom(\Z[\sqrt d],\F_r)=r$, and with a \emph{residual-coupling} theorem: validity forces $(d/p)=+1$ at the hidden prime factors $p\mid N$ with $p\nmid d$, and imposes nothing on the factor base. Explicit data at $B=200$ illustrate the results. The results identify the structural mechanism separating the two sieves. They do not claim a new running time.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Congruences of squares}
Both the quadratic sieve and the number field sieve factor a composite integer $N$ by producing a nontrivial congruence of squares
\[
X^2\equiv Y^2 \pmod N,\qquad X\not\equiv\pm Y\pmod N,
\]
from which $\gcd(X-Y,N)$ is a proper divisor of $N$. Each method collects \emph{relations}: objects whose norms factor completely over a factor base of primes up to a bound $B$. It records the exponent vectors modulo $2$ and finds a linear dependency. The heuristic running times are
\[
\text{QS: } L_N\!\left[\tfrac12,1\right],\qquad \text{NFS: } L_N\!\left[\tfrac13,\left(\tfrac{64}{9}\right)^{1/3}\right],
\]
where $L_N[\alpha,c]=\exp\big((c+o(1))(\ln N)^\alpha(\ln\ln N)^{1-\alpha}\big)$. The standard explanation for the gap is size. NFS norms are of size $N^{o(1)}$, while QS values are of size about $N^{1/2}$.

\subsection{The question of control}
A complementary question asks \emph{which parameter controls the column set}. A column is a factor-base prime that can actually divide a relation's norm. The set of live columns is the sieve's working vocabulary, and everything a sieve can tune lives on it. Earlier analysis showed that several proposed ``decoupling channels'' for the quadratic sieve, which tried to reweight or reprice its columns independently of $N$, are all provably closed for one reason. Every QS relation is a difference of squares tied to $N$, which forces $(N/r)=+1$ at every occurring prime. That analysis named a boundary. Columns outside the $N$-split set can appear only if the sieved quantity is not a difference of squares tied to $N$. This paper shows that the boundary is the number field sieve.

\subsection{Summary of results}
Let $\Pb$ be the odd primes $r\le B$, and let $S_N=\{r\in\Pb: r\nmid N\}$.
\begin{enumerate}[label=(\arabic*)]
\item \textbf{QS columns are slaved to $N$} (Propositions~\ref{prop:qs-iff}, \ref{prop:qs-forces}).
\item \textbf{Degree-one prime count:} $\#\Hom(\Z[\sqrt d],\F_r)=1+(d/r)$ (Theorem~\ref{thm:count}).
\item \textbf{Decoupling theorem:} all $2^{|S_N|}$ patterns are attained by valid $d$ (Theorem~\ref{thm:decouple}).
\item \textbf{Yield cancellation:} $\sum_{d=0}^{r-1}\#\Hom(\Z[\sqrt d],\F_r)=r$ (Theorem~\ref{thm:yield}).
\item \textbf{Residual coupling:} validity forces $(d/p)=+1$ at hidden primes $p\mid N$ (Theorem~\ref{thm:residual}).
\end{enumerate}

\section{Definitions and the split predicate}

Throughout, $r,p$ denote rational primes and $\F_r=\Z/r\Z$.

\begin{definition}
The \emph{odd factor base} is $\Pb=\{r\le B: r\text{ prime}, r\ne2\}$. For $a\in\Z$ and a prime $r$, we say that \emph{$r$ splits $a$} if $r\nmid a$ and some $x\in\{0,\dots,r-1\}$ has $r\mid x^2-a$. For $N,d\in\Z$,
\[
\CQS(N,B)=\{r\in\Pb: r\text{ splits }N\},\qquad \CNFS(d,B)=\{r\in\Pb: r\text{ splits }d\}.
\]
The \emph{coprime base} of $N$ is $S_N=\{r\in\Pb: r\nmid N\}$. An integer $d$ is \emph{valid for $N$ with root $m$} if $N\mid m^2-d$.
\end{definition}

The two column sets are the same function of different arguments. The whole content of this paper concerns which argument the factorer controls.

\begin{lemma}\label{lem:square}
For any prime $r$: $r$ splits $a$ if and only if $a\not\equiv0\pmod r$ and $a$ is a square in $\F_r$.
\end{lemma}
\begin{proof}
A witness $x$ gives $a\equiv x^2$. Conversely, if $a\equiv s^2$, the least nonnegative representative of $s$ is a witness in $\{0,\dots,r-1\}$.
\end{proof}

\begin{corollary}\label{cor:legendre}
For an odd prime $r$, $r$ splits $a$ if and only if $\leg ar=+1$.
\end{corollary}
\begin{proof}
If $r\mid a$ both sides fail. Otherwise this is the definition of the Legendre symbol together with Lemma~\ref{lem:square}.
\end{proof}

\begin{lemma}\label{lem:congr}
If $r$ is prime and $r\mid b-a$, then $r$ splits $a$ if and only if $r$ splits $b$.
\end{lemma}
\begin{proof}
By Lemma~\ref{lem:square} the predicate depends only on the image of $a$ in $\F_r$.
\end{proof}

\begin{lemma}\label{lem:intwit}
For $r\ge1$, some $x\in\Z$ has $r\mid x^2-a$ if and only if $a$ is a square in $\Z/r\Z$.
\end{lemma}
\begin{proof}
Reduce an integer witness modulo $r$, or lift a square root.
\end{proof}

\section{The quadratic sieve: columns governed by \texorpdfstring{$N$}{N}}

\begin{proposition}\label{prop:qs-congr}
If $N'\equiv N\pmod r$ for every $r\in\Pb$, then $\CQS(N',B)=\CQS(N,B)$.
\end{proposition}
\begin{proof}
Apply Lemma~\ref{lem:congr} to each $r\in\Pb$.
\end{proof}

\begin{proposition}\label{prop:qs-iff}
For $r\in\Pb$: $r\in\CQS(N,B)$ if and only if $r\nmid N$ and $r\mid x^2-N$ for some $x\in\Z$.
\end{proposition}
\begin{proof}
Lemmas~\ref{lem:square} and \ref{lem:intwit}.
\end{proof}

\begin{proposition}\label{prop:qs-forces}
Let $r$ be prime with $r\nmid N$, $r\nmid y$, and $r\mid x^2-Ny^2$. Then $r$ splits $N$. For odd $r$ this means $\leg Nr=+1$.
\end{proposition}
\begin{proof}
In $\F_r$, $x^2=Ny^2$ with $y\ne0$, so $N=(x/y)^2$ is a nonzero square.
\end{proof}

Thus no QS relation, however constructed, can place a prime $r\nmid N$ with $(N/r)\ne+1$ into a column. The integer being factored dictates the vocabulary.

\section{The quadratic number field sieve}

For $d\in\Z$ let $\Z[\sqrt d]=\{x+y\sqrt d: x,y\in\Z\}$ with the evident multiplication. We do not require $d$ to be squarefree or a non-square. Conjugation sends $x+y\sqrt d$ to $x-y\sqrt d$, and the norm is $\Nm(x+y\sqrt d)=x^2-dy^2$.

\begin{lemma}\label{lem:univ}
For any commutative ring $R$, ring homomorphisms $\Z[\sqrt d]\to R$ correspond bijectively to elements $s\in R$ with $s^2=d$, via $f\mapsto f(\sqrt d)$.
\end{lemma}
\begin{proof}
A homomorphism is determined by the image of $\sqrt d$, which must square to $d$. Conversely $x+y\sqrt d\mapsto x+ys$ is a ring homomorphism exactly when $s^2=d$.
\end{proof}

\begin{theorem}[Degree-one prime count]\label{thm:count}
For an odd prime $r$ and any $d\in\Z$,
\[
\#\Hom(\Z[\sqrt d],\F_r)=1+\leg dr.
\]
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:univ} the left side counts the $s\in\F_r$ with $s^2=d$. In a field of odd characteristic an element has $2$, $0$ or $1$ square roots according as it is a nonzero square, a non-square, or zero. That is $1+\chi(d)$, where $\chi$ is the quadratic character, here the Legendre symbol.
\end{proof}

\begin{proposition}\label{prop:ker}
Let $r$ be prime. The map $f\mapsto\ker f$ on $\Hom(\Z[\sqrt d],\F_r)$ is injective, and each $\ker f$ is a maximal ideal with residue field $\F_r$.
\end{proposition}
\begin{proof}
Each $f$ is surjective, since already $\Z$ maps onto $\F_r$, so $\ker f$ is maximal with quotient $\F_r$. If $\tilde s\in\Z$ represents $s=f(\sqrt d)$, then $\sqrt d-\tilde s\in\ker f$. If $\ker f=\ker g$, then $g(\sqrt d)=s$, so $f=g$ by Lemma~\ref{lem:univ}.
\end{proof}

Hence the homomorphisms $\Z[\sqrt d]\to\F_r$ are exactly the degree-one prime ideals above $r$. For $r$ odd, $r$ is \emph{split} (two primes, $\sqrt d\mapsto\pm s$) when $(d/r)=+1$, \emph{inert} (none) when $(d/r)=-1$, and \emph{ramified} (one) when $r\mid d$.

\begin{corollary}\label{cor:nfs-cols}
For $r\in\Pb$: $r\in\CNFS(d,B)$ if and only if $\#\Hom(\Z[\sqrt d],\F_r)=2$.
\end{corollary}

\begin{proposition}\label{prop:localise}
Let $r$ be prime with $r\nmid y$ and $r\mid x^2-dy^2$. Then some $f:\Z[\sqrt d]\to\F_r$ has $f(x+y\sqrt d)=0$. Conversely, if $f(x+y\sqrt d)=0$ for some such $f$, then $r\mid x^2-dy^2$.
\end{proposition}
\begin{proof}
Put $s=-x/y\in\F_r$. Then $s^2=d$, and the homomorphism with $\sqrt d\mapsto s$ kills $x+y\sqrt d$. For the converse, apply $f$ to $x^2-dy^2=(x+y\sqrt d)(x-y\sqrt d)$.
\end{proof}

Nothing in this section mentions $N$.

\section{The decoupling theorem}

\begin{theorem}[Decoupling theorem]\label{thm:decouple}
Let $N,m\in\Z$, $B\in\mathbb N$, and $T\subseteq S_N$. Then there exists $d\in\Z$ with
\[
N\mid m^2-d\qquad\text{and}\qquad \CNFS(d,B)\cap S_N=T.
\]
\end{theorem}
\begin{proof}
For $r\in S_N$ let $t_r=1$ if $r\in T$, and otherwise let $t_r$ be a quadratic non-residue modulo $r$. Such a non-residue exists since $r$ is odd and squaring is two-to-one on $\F_r^\times$. Then $r$ splits $t_r$ if and only if $r\in T$. The moduli $N$ and $r\in S_N$ are pairwise coprime: each $r$ is a prime not dividing $N$, and distinct primes are coprime. Equivalently, the ideals $(N)$ and $(r)$ are pairwise comaximal. By the Chinese Remainder Theorem there is $d$ with $d\equiv m^2\pmod N$ and $d\equiv t_r\pmod r$ for all $r\in S_N$. The first congruence is validity. By Lemma~\ref{lem:congr}, $r$ splits $d$ iff $r$ splits $t_r$ iff $r\in T$.
\end{proof}

\begin{corollary}\label{cor:patterns}
For all $N,m,B$, the set $\{\CNFS(d,B)\cap S_N: d\in\Z,\ N\mid m^2-d\}$ is the full power set of $S_N$. In particular exactly $2^{|S_N|}$ patterns are attained.
\end{corollary}

\begin{corollary}[The QS is the one point the attacker does not choose]\label{cor:qs-point}
The QS pattern $\CQS(N,B)\cap S_N$ is the NFS pattern of the valid member $d=N$, $m=0$. Moreover it is pinned by $N$: if $N'\equiv N\pmod r$ for all $r\in\Pb$, then $\CQS(N',B)=\CQS(N,B)$.
\end{corollary}
\begin{proof}
$N\mid 0^2-N$ and $\CQS(N,B)=\CNFS(N,B)$ by definition. The second claim is Proposition~\ref{prop:qs-congr}.
\end{proof}

\begin{remark}
The theorem holds for every fixed root $m$. Even an NFS variant with the map $\Z[\sqrt d]\to\Z/N\Z$ prescribed in advance keeps full column freedom. The QS is rigid because it also fixes $d=N$.
\end{remark}

\begin{remark}[Cost of the freedom]
The CRT solution is determined modulo $|N|\prod_{r\in S_N}r$, so the least solution may be that large. Larger $|d|$ inflates the norms $x^2-dy^2$ and lowers smoothness probability. The decoupling concerns which columns can be selected, not the cost of each selection.
\end{remark}

\section{Yield cancellation}

\begin{theorem}[Yield cancellation]\label{thm:yield}
For an odd prime $r$,
\[
\sum_{d=0}^{r-1}\#\Hom(\Z[\sqrt d],\F_r)=r.
\]
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:count} the summand is $1+(d/r)$. As $d$ runs over $0,\dots,r-1$ it covers $\F_r$ once, and the quadratic character sums to zero over a finite field of odd characteristic.
\end{proof}

Equivalently, the pairs $(d,s)\in\F_r^2$ with $s^2=d$ number $r$, since each $s$ determines $d$. Choosing $d$ redistributes split primes but cannot raise the average count above one per field.

\section{Residual coupling}

\begin{theorem}[Residual coupling]\label{thm:residual}
If $N\mid m^2-d$ and $p$ is a prime with $p\mid N$ and $p\nmid d$, then $p$ splits $d$. For odd $p$ this means $\leg dp=+1$.
\end{theorem}
\begin{proof}
$p\mid m^2-d$, so $m$ is an integer witness. Apply Lemmas~\ref{lem:intwit} and \ref{lem:square}.
\end{proof}

\begin{proposition}
For a prime $p\nmid d$, some $m\in\Z$ has $p\mid m^2-d$ if and only if $p$ splits $d$.
\end{proposition}

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
primes & constraint imposed by validity\\
\midrule
factor-base primes $r\in S_N$ & none: all $2^{|S_N|}$ patterns occur\\
hidden primes $p\mid N$, $p\nmid d$ & forced: $(d/p)=+1$\\
\bottomrule
\end{tabular}
\end{center}

The dependence on $N$ has moved onto the secret factors of $N$, which never belong to the factor base.

\section{Numerical data}

All counts are over $\mathcal P_{200}$ ($45$ odd primes).

\textbf{One field, two moduli.} The field $d=-7$ is valid for $N=11$ (as $2^2+7=11$) and for $N=23$ (as $4^2+7=23$). Its column set $\CNFS(-7,200)$ has $21$ elements, the same object for both moduli. Counting $r=2$, which splits since $-7\equiv1\pmod 8$, there are $22$ split primes up to $200$. By contrast:
\begin{center}
\begin{tabular}{@{}cc@{}}
\toprule
$N$ & $|\CQS(N,200)|$\\
\midrule
$11$ & $20$\\
$23$ & $19$\\
$15$ & $21$\\
$47$ & $25$\\
\bottomrule
\end{tabular}
\end{center}
and $\CQS(11,200)\ne\CQS(23,200)$.

\textbf{Decoupling in miniature.} For $N=253=11\cdot23$, $m=5$, $B=13$, we have $S_N=\{3,5,7,13\}$ and QS pattern $\{3,7\}$. The construction of Theorem~\ref{thm:decouple} yields $16$ valid fields with $16$ distinct patterns. For example $T=\varnothing$ gives $d=327407$, $T=S_N$ gives $d=318046$, and $T=\{3,7\}$ gives $d=195847$.

\textbf{Yield cancellation.} For $r=3,5,\dots,31$, summing the number of square roots of $d$ modulo $r$ over $d=0,\dots,r-1$ returns $r$.

\textbf{Residual coupling.} For $N=1009\cdot1013$ and $d=m^2-kN$ over several $m,k$, both $(d/1009)$ and $(d/1013)$ equal $+1$.

\section{Algorithms}

\begin{algorithm}[Column sets]
Given $a$ and $B$, sieve the odd primes $r\le B$. For each, compute $a^{(r-1)/2}\bmod r$ and keep $r$ iff the result is $1$ (Euler's criterion). Cost: $O(\pi(B)\log B)$ modular multiplications.
\end{algorithm}

\begin{algorithm}[Field with prescribed column pattern]
Given $N,m,B,T\subseteq S_N$: set $t_r=1$ for $r\in T$, and set $t_r$ to the least non-residue modulo $r$ for $r\in S_N\setminus T$. Solve $d\equiv m^2\ (N)$, $d\equiv t_r\ (r)$ by incremental CRT and return $d$. Cost: $O(|S_N|)$ CRT steps on integers of size at most $|N|\prod_{r\in S_N}r$.
\end{algorithm}

\begin{algorithm}[Degree-one primes above $r$]
Given $d$ and an odd prime $r$, return the square roots $s$ of $d$ in $\F_r$, using Tonelli--Shanks when $(d/r)=1$, $[0]$ when $r\mid d$, and $[\,]$ otherwise. Each $s$ corresponds to the prime ideal $(r,\sqrt d-s)$. The list has length $1+(d/r)$.
\end{algorithm}

\section{Discussion}

The NFS running time $L_N[1/3]$ is classical, and we make no running-time claim. The contribution is the mechanism at the level of the column set. The QS channels are closed because every column-level quantity is a function of the symbols $(N/r)$ (Proposition~\ref{prop:qs-forces}). The escape is that in the NFS these quantities are functions of $(d/r)$ (Theorem~\ref{thm:count}), over a family in which all patterns occur (Theorem~\ref{thm:decouple}). The escape costs nothing in average yield (Theorem~\ref{thm:yield}) but inflates $|d|$. The modulus $N$ still enters only at its own hidden primes (Theorem~\ref{thm:residual}). Corollary~\ref{cor:qs-point} makes precise the folklore remark that the QS is a degenerate degree-two NFS.

\emph{Scope.} We treat the quadratic order $\Z[\sqrt d]$. Practical NFS uses degree $k\approx(3\ln N/\ln\ln N)^{1/3}$ and two-sided relations. The prime $2$ is excluded from the odd factor base for uniformity, since its splitting is governed by $d\bmod 8$.

\section{Future directions}

\begin{conjecture}[Higher-degree column freedom]
For monic irreducible $f$ of degree $k$ with $f(m)\equiv0\pmod N$, the vector of root counts $(\#\{x\bmod r: f(x)\equiv0\})_{r\in S}$ takes every value in $\prod_r\{0,\dots,k\}$ compatible with an admissible splitting type, as $f$ ranges over polynomials valid for $N$. Validity is a congruence modulo $N$ only, and CRT separates it from congruences modulo factor-base primes.
\end{conjecture}

\begin{conjecture}[Hidden-prime leakage bound]
Any statistic of the NFS column set computable from $\{(d/r)\}_{r\in S}$ is independent of the factorisation of $N$. The only $N$-information carried by a valid $d$ is the vector $((d/p))_{p\mid N}$, which is forced to be all $+1$.
\end{conjecture}

\begin{conjecture}[Two-sided column freedom]
In the two-sided quadratic NFS, with $a-bm$ on the rational side and $a-b\sqrt d$ on the algebraic side, the joint column pattern is free in $d$ for fixed $(N,m)$, and the expected number of algebraic columns over a CRT period of $d$ is $|S|$.
\end{conjecture}

\begin{conjecture}[Field-choice lever with a smoothness price]
Making every $r\in S$ split forces $|d|\gtrsim\prod_{r\in S}r/2^{|S|}$ for the least valid solution in natural families, trading column count against norm size. The optimum should reproduce the degree-versus-coefficient balance of NFS polynomial selection.
\end{conjecture}

\section{Conclusion}

The quadratic sieve and the quadratic number field sieve use the same column rule, ``primes at which the parameter is a nonzero square'', applied to different parameters. In the QS the parameter is $N$, which is given. In the NFS it is $d$, which is chosen subject only to a congruence modulo $N$, and by the Chinese Remainder Theorem that congruence is invisible on the factor base. The freedom is complete (all $2^{|S|}$ patterns), zero-sum in average yield, and leaves a single trace of $N$: forced splitting at its own hidden primes.

