from __future__ import annotations


def primes_up_to(B: int) -> list[int]:
    """Sieve of Eratosthenes."""
    if B < 2:
        return []
    is_p = bytearray([1]) * (B + 1)
    is_p[0:2] = b"\x00\x00"
    for i in range(2, int(B ** 0.5) + 1):
        if is_p[i]:
            is_p[i * i :: i] = bytearray(len(is_p[i * i :: i]))
    return [i for i in range(B + 1) if is_p[i]]


def legendre(a: int, r: int) -> int:
    """Legendre symbol (a/r) for an odd prime r via Euler's criterion."""
    t = pow(a % r, (r - 1) // 2, r)
    return -1 if t == r - 1 else t


def column_set(a: int, B: int) -> list[int]:
    """Odd primes r <= B with (a/r) = +1.
    a = N gives the quadratic-sieve columns; a = d gives the quadratic-NFS columns."""
    return [r for r in primes_up_to(B) if r != 2 and legendre(a, r) == 1]


if __name__ == "__main__":
    B = 200
    print("NFS d=-7 :", len(column_set(-7, B)))
    for N in (11, 23, 15, 47):
        print(f"QS  N={N:<3}:", len(column_set(N, B)))

from __future__ import annotations


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    f = 2
    while f * f <= n:
        if n % f == 0:
            return False
        f += 1
    return True


def legendre(a: int, r: int) -> int:
    t = pow(a % r, (r - 1) // 2, r)
    return -1 if t == r - 1 else t


def least_nonresidue(r: int) -> int:
    return next(t for t in range(2, r) if legendre(t, r) == -1)


def coprime_base(N: int, B: int) -> list[int]:
    return [r for r in range(3, B + 1) if is_prime(r) and N % r != 0]


def field_with_pattern(N: int, m: int, B: int, target: set[int]) -> int:
    """Return d with N | m^2 - d whose split primes on the coprime base are exactly `target`.

    Incremental Chinese Remainder Theorem over the pairwise coprime moduli |N| and r in S_N.
    """
    S = coprime_base(N, B)
    if not target <= set(S):
        raise ValueError("target must be a subset of the coprime base")
    M = abs(N)
    x = (m * m) % M
    for r in S:
        t = 1 if r in target else least_nonresidue(r)
        k = ((t - x) * pow(M, -1, r)) % r
        x, M = x + M * k, M * r
    return x


if __name__ == "__main__":
    from itertools import product
    N, m, B = 253, 5, 13
    S = coprime_base(N, B)
    seen = set()
    for bits in product((0, 1), repeat=len(S)):
        T = {r for r, b in zip(S, bits) if b}
        d = field_with_pattern(N, m, B, T)
        assert (m * m - d) % N == 0
        got = frozenset(r for r in S if legendre(d, r) == 1)
        assert got == T
        seen.add(got)
        print(sorted(T), "->", d)
    print(len(seen), "patterns =", 2 ** len(S))

from __future__ import annotations


def legendre(a: int, r: int) -> int:
    t = pow(a % r, (r - 1) // 2, r)
    return -1 if t == r - 1 else t


def tonelli_shanks(a: int, r: int) -> int:
    """A square root of a nonzero quadratic residue a modulo the odd prime r."""
    a %= r
    if r % 4 == 3:
        return pow(a, (r + 1) // 4, r)
    q, s = r - 1, 0
    while q % 2 == 0:
        q //= 2
        s += 1
    z = next(z for z in range(2, r) if legendre(z, r) == -1)
    M, c, t, R = s, pow(z, q, r), pow(a, q, r), pow(a, (q + 1) // 2, r)
    while t != 1:
        i, t2 = 0, t
        while t2 != 1:
            t2 = t2 * t2 % r
            i += 1
        b = pow(c, 1 << (M - i - 1), r)
        M, c, t, R = i, b * b % r, t * b * b % r, R * b % r
    return R


def degree_one_primes(d: int, r: int) -> list[int]:
    """Images s of sqrt(d) for the ring homomorphisms Z[sqrt d] -> F_r.
    Each s corresponds to the degree-one prime ideal (r, sqrt(d) - s).  Length = 1 + (d/r)."""
    L = legendre(d, r)
    if L == 0:
        return [0]
    if L == -1:
        return []
    s = tonelli_shanks(d, r)
    return sorted({s, (r - s) % r})


if __name__ == "__main__":
    for r in (3, 5, 7, 11, 13, 17, 29, 41):
        total = sum(len(degree_one_primes(d, r)) for d in range(r))
        assert all(len(degree_one_primes(d, r)) == 1 + legendre(d, r) for d in range(-50, 50))
        print(f"r={r:>2}: sum over d of #primes = {total}")
    print("d=-7, r=11 :", degree_one_primes(-7, 11))
